package dev.linqfy.bigCasares.modules.mythicdungeons.worldgen.thirdparty;

import dev.linqfy.bigCasares.dimension.NamespacedId;
import dev.linqfy.bigCasares.modules.mythicdungeons.worldgen.MythicDungeonTheme;
import dev.linqfy.bigCasares.modules.mythicdungeons.worldgen.MythicExtraPiece;
import dev.linqfy.bigCasares.modules.mythicdungeons.worldgen.MythicExtraPiece.Role;
import dev.linqfy.bigCasares.modules.mythicdungeons.worldgen.MythicTemplateSource;

import java.util.ArrayList;
import java.util.List;

/**
 * Dungeons generated by the transcribed Doomlike Dungeons planner ({@link DoomlikeLayout},
 * {@link DoomlikeBuilder}). Per culture: {@link #VARIANTS} complete multi-room levels offered as
 * {@link Role#FULL_DUNGEON} starts (a walled complex at the surface whose entrance node holds the
 * descent to the boss arena, with side-room doorways and gates in its outer walls) and
 * {@link #VARIANTS} single Doomlike rooms as {@link Role#SIDE_ROOM}s. The theme per culture is in
 * {@link DoomlikeTheme#BY_CULTURE}. Every layout is seeded by culture, kind and variant index, so
 * the pack bytes are stable.
 */
public final class DoomlikeDungeonsSource implements MythicTemplateSource {

    static final int VARIANTS = 2;
    /** A full dungeon must keep at least this many rooms after the connectivity pass. */
    private static final int MIN_ROOMS = 4;
    private static final int ATTEMPTS = 16;

    @Override
    public List<MythicExtraPiece> piecesFor(String culture) {
        MythicDungeonTheme theme = MythicDungeonTheme.all().stream()
            .filter(candidate -> candidate.culture().equals(culture)).findFirst().orElse(null);
        List<DoomlikeTheme> themes = DoomlikeTheme.BY_CULTURE.get(culture);
        if (theme == null || themes == null) {
            return List.of();
        }
        List<MythicExtraPiece> pieces = new ArrayList<>();
        for (int variant = 0; variant < VARIANTS; variant++) {
            DoomlikeTheme doomlike = themes.get(variant % themes.size());
            String name = "doomlike/dungeon_" + variant;
            pieces.add(new MythicExtraPiece(name, dungeon(theme, doomlike, variant)
                .build(NamespacedId.of("bigc_myth", "third_party/" + culture + "/" + name)),
                Role.FULL_DUNGEON, ThirdPartyBlocks.DESCENT, null, 1));
        }
        for (int variant = 0; variant < VARIANTS; variant++) {
            DoomlikeTheme doomlike = themes.get(variant % themes.size());
            String name = "doomlike/room_" + variant;
            int depth = 9 + 2 * variant;
            DoomlikeLayout layout = DoomlikeLayout.singleRoom(doomlike, seed(culture, "room", variant, 0), 9, depth);
            layout.openNorthDoor(4);
            pieces.add(new MythicExtraPiece(name, DoomlikeBuilder.sideRoom(layout, theme, 4)
                .build(NamespacedId.of("bigc_myth", "third_party/" + culture + "/" + name)),
                Role.SIDE_ROOM, ThirdPartyBlocks.ENTRY, null, 2));
        }
        return pieces;
    }

    /** The first seed (in a fixed sequence) whose layout keeps enough rooms. */
    static TemplateGrid dungeon(MythicDungeonTheme theme, DoomlikeTheme doomlike, int variant) {
        for (int attempt = 0; attempt < ATTEMPTS; attempt++) {
            DoomlikeLayout layout = DoomlikeLayout.dungeon(doomlike, seed(theme.culture(), "dungeon", variant, attempt));
            long kept = layout.rooms.stream().filter(room -> !room.removed && !room.isSubroom).count();
            if (layout.entrance != null && !layout.entrance.removed && kept >= MIN_ROOMS) {
                return DoomlikeBuilder.dungeon(layout, theme);
            }
        }
        throw new IllegalStateException("No usable Doomlike layout for " + theme.culture() + " variant " + variant);
    }

    static long seed(String culture, String kind, int variant, int attempt) {
        return (("doomlike:" + culture + ":" + kind + ":" + variant).hashCode() & 0xffffffffL) * 31L + attempt;
    }
}
